//! S+N++ bytecode compiler and virtual machine.
use std::collections::{HashMap, BTreeMap};
use std::sync::mpsc;
use std::thread;
use std::sync::atomic::Ordering;
use crate::ast::{Expr, Function, Stmt, Type, Value};
use crate::lexer::Token;
use crate::{parser, typecheck};
use crate::{channel_table, thread_table, NEXT_CHANNEL_ID, NEXT_THREAD_ID};
#[derive(Debug,Clone)] enum Op { Const(Value), Load(String), Store(String), Add, Sub, Mul, Div, Eq, Ne, Lt, Lte, Gt, Gte, Call(String,usize), Print, Pop, JumpIfFalse(usize), Jump(usize), Return, Halt }
#[derive(Debug,Clone)] struct Chunk { code:Vec<Op> }
fn show(v:&Value)->String{match v{Value::Int(x)=>x.to_string(),Value::Str(x)=>x.clone(),Value::Bool(x)=>x.to_string(),Value::Unit=>"unit".into(),Value::Thread(id)=>format!("thread({id})"),Value::Channel(id)=>format!("channel({id})"),Value::List(items)=>format!("list(len={})",items.len()),Value::Map(items)=>format!("map(len={})",items.len())}}
fn truth(v:&Value)->bool{matches!(v,Value::Bool(true))||matches!(v,Value::Int(x)if *x!=0)}
fn bin(a:Value,o:&Token,b:Value)->Result<Value,String>{match(a,b,o){(Value::Int(x),Value::Int(y),Token::Plus)=>Ok(Value::Int(x+y)),(Value::Int(x),Value::Int(y),Token::Minus)=>Ok(Value::Int(x-y)),(Value::Int(x),Value::Int(y),Token::Star)=>Ok(Value::Int(x*y)),(Value::Int(x),Value::Int(y),Token::Slash)=>Ok(Value::Int(x/y)),(Value::Int(x),Value::Int(y),Token::EqEq)=>Ok(Value::Bool(x==y)),(Value::Int(x),Value::Int(y),Token::BangEq)=>Ok(Value::Bool(x!=y)),(Value::Int(x),Value::Int(y),Token::Lt)=>Ok(Value::Bool(x<y)),(Value::Int(x),Value::Int(y),Token::Lte)=>Ok(Value::Bool(x<=y)),(Value::Int(x),Value::Int(y),Token::Gt)=>Ok(Value::Bool(x>y)),(Value::Int(x),Value::Int(y),Token::Gte)=>Ok(Value::Bool(x>=y)),(Value::Str(x),Value::Str(y),Token::Plus)=>Ok(Value::Str(x+&y)),(x,y,Token::EqEq)=>Ok(Value::Bool(x==y)),(x,y,Token::BangEq)=>Ok(Value::Bool(x!=y)),_=>Err("invalid operands".into())}}
fn compile_expr(x:&Expr,c:&mut Chunk)->Result<(),String>{match x{Expr::Int(v)=>c.code.push(Op::Const(Value::Int(*v))),Expr::Str(v)=>c.code.push(Op::Const(Value::Str(v.clone()))),Expr::Bool(v)=>c.code.push(Op::Const(Value::Bool(*v))),Expr::Var(n)=>c.code.push(Op::Load(n.clone())),Expr::Binary(a,o,b)=>{compile_expr(a,c)?;compile_expr(b,c)?;c.code.push(match o{Token::Plus=>Op::Add,Token::Minus=>Op::Sub,Token::Star=>Op::Mul,Token::Slash=>Op::Div,Token::EqEq=>Op::Eq,Token::BangEq=>Op::Ne,Token::Lt=>Op::Lt,Token::Lte=>Op::Lte,Token::Gt=>Op::Gt,Token::Gte=>Op::Gte,_=>return Err("invalid bytecode operator".into())})},Expr::Call(n,a)=>{for x in a{compile_expr(x,c)?}c.code.push(if n=="print"{Op::Print}else{Op::Call(n.clone(),a.len())})}}Ok(())}
fn compile_stmts(xs:&[Stmt],c:&mut Chunk)->Result<(),String>{for s in xs{match s{Stmt::Let(n,x)|Stmt::Assign(n,x)=>{compile_expr(x,c)?;c.code.push(Op::Store(n.clone()));},Stmt::Decl(_,_)=>{},Stmt::Expr(x)=>{compile_expr(x,c)?;c.code.push(Op::Pop);},Stmt::Return(x)=>{compile_expr(x,c)?;c.code.push(Op::Return);},Stmt::If(cond,a,b)=>{compile_expr(cond,c)?;let jf=c.code.len();c.code.push(Op::JumpIfFalse(0));compile_stmts(a,c)?;let j=c.code.len();c.code.push(Op::Jump(0));let else_ip=c.code.len();compile_stmts(b,c)?;let end=c.code.len();c.code[jf]=Op::JumpIfFalse(else_ip);c.code[j]=Op::Jump(end);},Stmt::While(cond,b)=>{let start=c.code.len();compile_expr(cond,c)?;let jf=c.code.len();c.code.push(Op::JumpIfFalse(0));compile_stmts(b,c)?;c.code.push(Op::Jump(start));let end=c.code.len();c.code[jf]=Op::JumpIfFalse(end);}}}Ok(())}
fn compile_functions(fs:&[Function])->Result<HashMap<String,(Vec<String>,Chunk)>,String>{let mut out=HashMap::new();for f in fs{let mut c=Chunk{code:Vec::new()};compile_stmts(&f.body,&mut c)?;c.code.push(Op::Const(Value::Unit));c.code.push(Op::Return);out.insert(f.name.clone(),(f.params.clone(),c));}Ok(out)}
pub struct BytecodeVm{funcs:HashMap<String,(Vec<String>,Chunk)>}
impl BytecodeVm{fn call(&self,n:&str,args:Vec<Value>)->Result<Value,String>{if n=="print"{for v in args{println!("{}",show(&v))}return Ok(Value::Unit)}if n=="str_len"{let s=match args.first(){Some(Value::Str(s))=>s,_=>return Err("str_len expects String".into())};return Ok(Value::Int(s.chars().count()as i64))}if n=="str_contains"{let s=match args.first(){Some(Value::Str(s))=>s,_=>return Err("str_contains expects String as first argument".into())};let needle=match args.get(1){Some(Value::Str(s))=>s,_=>return Err("str_contains expects String as second argument".into())};return Ok(Value::Bool(s.contains(needle)))}if n=="str_upper"||n=="str_lower"||n=="str_trim"{let s=match args.first(){Some(Value::Str(s))=>s,_=>return Err(format!("{n} expects String"))};let out=if n=="str_upper"{s.to_uppercase()}else if n=="str_lower"{s.to_lowercase()}else{s.trim().to_string()};return Ok(Value::Str(out))}if n=="str_concat"{let a=match args.first(){Some(Value::Str(s))=>s,_=>return Err("str_concat expects String arguments".into())};let b=match args.get(1){Some(Value::Str(s))=>s,_=>return Err("str_concat expects String arguments".into())};return Ok(Value::Str(format!("{a}{b}")))}if n=="list"{return Ok(Value::List(args))}if n=="list_push"{let list=match args.first(){Some(Value::List(items))=>items.clone(),_=>return Err("list_push expects List as first argument".into())};let mut out=list;out.push(args.get(1).cloned().ok_or("list_push expects a value")?);return Ok(Value::List(out))}if n=="list_len"{let list=match args.first(){Some(Value::List(items))=>items,_=>return Err("list_len expects List".into())};return Ok(Value::Int(list.len()as i64))}if n=="list_get"{let list=match args.first(){Some(Value::List(items))=>items,_=>return Err("list_get expects List as first argument".into())};let index=match args.get(1){Some(Value::Int(index))=>*index,_=>return Err("list_get expects Int index".into())};if index<0{return Err("list_get index cannot be negative".into())}return list.get(index as usize).cloned().ok_or_else(||"list_get index out of bounds".into())}if n=="list_set"{let list=match args.first(){Some(Value::List(items))=>items.clone(),_=>return Err("list_set expects List as first argument".into())};let index=match args.get(1){Some(Value::Int(index))=>*index,_=>return Err("list_set expects Int index".into())};if index<0||index as usize>=list.len(){return Err("list_set index out of bounds".into())}let mut out=list;out[index as usize]=args.get(2).cloned().ok_or("list_set expects a value")?;return Ok(Value::List(out))}if n=="list_concat"{let a=match args.first(){Some(Value::List(items))=>items.clone(),_=>return Err("list_concat expects List arguments".into())};let b=match args.get(1){Some(Value::List(items))=>items.clone(),_=>return Err("list_concat expects List arguments".into())};let mut out=a;out.extend(b);return Ok(Value::List(out))}if n=="map"{if args.len()%2!=0{return Err("map expects key/value pairs".into())}let mut out=BTreeMap::new();let mut i=0;while i<args.len(){let key=match &args[i]{Value::Str(key)=>key.clone(),_=>return Err("map keys must be String".into())};out.insert(key,args[i+1].clone());i+=2}return Ok(Value::Map(out))}if n=="map_set"{let map=match args.first(){Some(Value::Map(items))=>items.clone(),_=>return Err("map_set expects Map as first argument".into())};let key=match args.get(1){Some(Value::Str(key))=>key.clone(),_=>return Err("map_set expects String key".into())};let mut out=map;out.insert(key,args.get(2).cloned().ok_or("map_set expects a value")?);return Ok(Value::Map(out))}if n=="map_get"{let map=match args.first(){Some(Value::Map(items))=>items,_=>return Err("map_get expects Map as first argument".into())};let key=match args.get(1){Some(Value::Str(key))=>key,_=>return Err("map_get expects String key".into())};return map.get(key).cloned().ok_or_else(||"map key not found".into())}if n=="map_has"{let map=match args.first(){Some(Value::Map(items))=>items,_=>return Err("map_has expects Map as first argument".into())};let key=match args.get(1){Some(Value::Str(key))=>key,_=>return Err("map_has expects String key".into())};return Ok(Value::Bool(map.contains_key(key)))}if n=="channel"{let(id_tx,id_rx)=mpsc::channel();let id=NEXT_CHANNEL_ID.fetch_add(1,Ordering::Relaxed);channel_table().lock().unwrap().insert(id,(id_tx,id_rx));return Ok(Value::Channel(id))}if n=="send"{let id=match args.first(){Some(Value::Channel(i))=>*i,_=>return Err("send expects channel".into())};let value=args.get(1).cloned().ok_or("send expects value")?;let table=channel_table().lock().unwrap();let tx=table.get(&id).ok_or("unknown channel")?.0.clone();tx.send(value).map_err(|_|"channel disconnected".to_string())?;return Ok(Value::Unit)}if n=="receive"{let id=match args.first(){Some(Value::Channel(i))=>*i,_=>return Err("receive expects channel".into())};let table=channel_table().lock().unwrap();let rx=table.get(&id).ok_or("unknown channel")?.1.recv().map_err(|_|"channel disconnected".to_string())?;return Ok(rx)}if n=="spawn"{let target=match args.first(){Some(Value::Str(s))=>s.clone(),_=>return Err("spawn expects a function name string".into())};let worker_args=args.into_iter().skip(1).collect::<Vec<_>>();let funcs=self.funcs.clone();let id=NEXT_THREAD_ID.fetch_add(1,Ordering::Relaxed);let handle=thread::spawn(move||BytecodeVm{funcs}.call(&target,worker_args).unwrap_or(Value::Unit));thread_table().lock().unwrap().insert(id,handle);return Ok(Value::Thread(id))}if n=="join"{let id=match args.first(){Some(Value::Thread(i))=>*i,_=>return Err("join expects a thread handle".into())};let handle=thread_table().lock().unwrap().remove(&id).ok_or("unknown thread handle")?;return handle.join().map_err(|_|"thread panicked".into())}let(fparams,chunk)=self.funcs.get(n).ok_or_else(||format!("unknown function `{n}`"))?.clone();let mut locals=HashMap::new();for(i,p)in fparams.iter().enumerate(){locals.insert(p.clone(),args.get(i).cloned().unwrap_or(Value::Unit));}let mut stack=Vec::new();let mut ip=0;while ip<chunk.code.len(){match &chunk.code[ip]{Op::Const(v)=>stack.push(v.clone()),Op::Load(n)=>stack.push(locals.get(n).cloned().ok_or_else(||format!("undefined variable `{n}`"))?),Op::Store(n)=>{let v=stack.pop().ok_or("stack underflow")?;locals.insert(n.clone(),v);},Op::Add|Op::Sub|Op::Mul|Op::Div|Op::Eq|Op::Ne|Op::Lt|Op::Lte|Op::Gt|Op::Gte=>{let b=stack.pop().ok_or("stack underflow")?;let a=stack.pop().ok_or("stack underflow")?;let op=match &chunk.code[ip]{Op::Add=>Token::Plus,Op::Sub=>Token::Minus,Op::Mul=>Token::Star,Op::Div=>Token::Slash,Op::Eq=>Token::EqEq,Op::Ne=>Token::BangEq,Op::Lt=>Token::Lt,Op::Lte=>Token::Lte,Op::Gt=>Token::Gt,Op::Gte=>Token::Gte,_=>unreachable!()};stack.push(bin(a,&op,b)?);},Op::Call(n,c)=>{let mut a=Vec::new();for _ in 0..*c{a.push(stack.pop().ok_or("stack underflow")?)}a.reverse();stack.push(self.call(n,a)?);},Op::Print=>{let v=stack.pop().ok_or("stack underflow")?;println!("{}",show(&v));stack.push(Value::Unit);},Op::Pop=>{stack.pop();},Op::JumpIfFalse(to)=>{let v=stack.pop().ok_or("stack underflow")?;if !truth(&v){ip=*to;continue}},Op::Jump(to)=>{ip=*to;continue},Op::Return=>return Ok(stack.pop().unwrap_or(Value::Unit)),Op::Halt=>return Ok(Value::Unit)}ip+=1}Ok(Value::Unit)}}
pub fn build_artifact(src:&str)->Result<Vec<u8>,String>{let program=parser::parse_program(src)?;crate::stdlib::resolve(&program.imports)?;let fs=program.functions;typecheck::check(&fs)?;let funcs=compile_functions(&fs)?;let mut bytes=b"SNPBC1\n".to_vec();bytes.extend(format!("{funcs:?}").as_bytes());Ok(bytes)}
pub fn execute(src:&str)->Result<Value,String>{let program=parser::parse_program(src)?;crate::stdlib::resolve(&program.imports)?;let fs=program.functions;typecheck::check(&fs)?;let funcs=compile_functions(&fs)?;BytecodeVm{funcs}.call("main",vec![])}

#[cfg(test)] mod tests {use super::*;#[test]fn worker_can_receive_channel_argument(){let s="fn worker(ch:Channel){send(ch,99);} fn main(){let ch=channel();let t=spawn(\"worker\",ch);join(t);print(receive(ch));}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn channel_send_receive_round_trip(){let s="fn main(){let ch=channel(); send(ch,42); print(receive(ch));}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn recursive_stack_frames_are_isolated(){let s="fn fact(n:Int)->Int{if n==0{return 1;} return n*fact(n-1);} fn main()->Int{return fact(5);}";assert_eq!(execute(s),Ok(Value::Int(120)));}#[test]fn branch_move_is_conservatively_merged(){let s="fn consume(x:String){} fn main(){let s=\"x\"; if true {consume(s);} else {} print(s);}";assert!(execute(s).unwrap_err().contains("use of moved value"));}#[test]fn arithmetic(){let s="fn main(){ print(2+3*4); return 0; }";assert_eq!(execute(s),Ok(Value::Int(0)));}#[test]fn function_call(){let s="fn add(a:Int,b:Int){return a+b;} fn main(){return add(2,3);}";assert_eq!(execute(s),Ok(Value::Int(5)));}#[test]fn unknown_function_is_diagnostic(){let s="fn main(){missing();}";assert!(execute(s).unwrap_err().contains("unknown function"));}#[test]fn type_mismatch_is_diagnostic(){let s="fn add(a:Int,b:Int)->Int{return a+b;} fn main()->Int{return add(2,\"x\");}";assert!(execute(s).unwrap_err().contains("expects Int"));}#[test]fn condition_must_be_bool(){let s="fn main(){if 1 { print(1); }}";assert!(execute(s).unwrap_err().contains("condition must be Bool"));}#[test]fn string_move_is_tracked(){let s="fn consume(x:String){print(x);} fn main(){let a=\"hello\"; consume(a); print(a);}";assert!(execute(s).unwrap_err().contains("use of moved value"));}#[test]fn immutable_borrow_preserves_owner(){let s="fn view(x:&String){print(x);} fn main(){let a=\"hello\"; view(a); print(a);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn mutable_reference_syntax_is_valid(){let s="fn update(x:&mut String){print(x);} fn main(){let a=\"hello\"; update(a); print(a);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn spawn_and_join_run_worker(){let s="fn worker(){print(\"worker\");} fn main(){let t=spawn(\"worker\"); join(t);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn multiple_workers_can_join(){let s="fn worker(){return 7;} fn main(){let a=spawn(\"worker\"); let b=spawn(\"worker\"); join(a); join(b);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn function_locals_do_not_leak(){let s="fn helper(){let secret=1;} fn main(){print(secret);}";assert!(execute(s).unwrap_err().contains("undefined variable"));}#[test]fn assignment_requires_existing_variable(){let s="fn main(){missing=1;}";assert!(execute(s).unwrap_err().contains("undefined variable"));}#[test]fn lexical_shadowing_keeps_outer_value(){let s="fn main(){let x=1; if true {let x=2; print(x);} print(x);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn branch_must_definitely_assign(){let s="fn main(){let x:Int; if true {x=1;} print(x);}";assert!(execute(s).unwrap_err().contains("uninitialized variable"));}#[test]fn both_branches_assign_value(){let s="fn main(){let x:Int; if true {x=1;} else {x=2;} print(x);}";assert_eq!(execute(s),Ok(Value::Unit));}#[test]fn loop_assignment_is_not_definite_after_loop(){let s="fn main(){let x:Int; while false {x=1;} print(x);}";assert!(execute(s).unwrap_err().contains("uninitialized variable"));}}

#[cfg(test)]
mod stdlib_api_tests {
    use super::*;

    #[test]
    fn string_and_collection_functions_execute() {
        let source = "import std.string; import std.collections; fn main()->Int{ let xs=list(1,2); let ys=list_push(xs,3); print(str_upper(\"hello\")); print(str_contains(\"hello\",\"ell\")); print(list_get(ys,1)); return list_len(ys); }";
        assert_eq!(execute(source), Ok(Value::Int(3)));
    }
}

#[cfg(test)]
mod advanced_collection_tests {
    use super::*;

    #[test]
    fn immutable_list_updates_and_map_access_work() {
        let source = "import std.collections; fn main()->Int{ let a=list(1,2); let b=list_set(a,0,9); let c=list_concat(a,b); let m=map(\"answer\",42); let n=map_set(m,\"extra\",7); print(list_get(c,0)); print(map_get(n,\"answer\")); print(map_has(n,\"extra\")); return list_len(c); }";
        assert_eq!(execute(source), Ok(Value::Int(4)));
    }

    #[test]
    fn list_set_rejects_out_of_bounds_index() {
        let source = "import std.collections; fn main(){ let a=list(1); print(list_set(a,4,9)); }";
        assert!(execute(source).unwrap_err().contains("list_set index out of bounds"));
    }

    #[test]
    fn map_requires_string_keys_and_known_values() {
        let source = "import std.collections; fn main(){ let m=map(\"x\",1); print(map_get(m,\"missing\")); }";
        assert!(execute(source).unwrap_err().contains("map key not found"));
    }
}
